from pathlib import Path
import json,hashlib
from PIL import Image
O=Path(__file__).resolve().parent
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def read(p):return json.loads(Path(p).read_text(encoding='utf-8-sig'))
def save(p,v):Path(p).write_text(json.dumps(v,ensure_ascii=False,indent=2),encoding='utf-8')
sel=read(O/'final-selection.json')
# Scalp crown is hidden: approximate continuation of forehead/temple and ear-level cranial oval.
# Rectangles describe visible face envelope/proxy, NOT a claim of precise segmented skin area.
manual=[
 dict(crown=140,crownError=35,chin=366,face=[550,235,195,131],footX=635,bodyX=[330,916]),
 dict(crown=135,crownError=35,chin=386,face=[535,230,206,156],footX=630,bodyX=[330,912]),
 dict(crown=160,crownError=40,chin=487,face=[473,300,230,187],footX=578,bodyX=[295,843]),
 dict(crown=210,crownError=50,chin=663,face=[467,405,337,258],footX=615,bodyX=[274,982]),
 dict(crown=220,crownError=55,chin=686,face=[476,415,344,271],footX=626,bodyX=[270,986])]
labels=['기존','1 · 절제 확대','2 · 얼굴·몸 균형','3 · 큰 두상 SD','4 · 얼굴 우선']
entries=[]
for i,m in enumerate(manual):
    file='original.png' if i==0 else f'variant-{i}-front.png';p=O/file;im=Image.open(p);w,h=im.size;a=im.getchannel('A');threshold=a.point(lambda x:255 if x>=32 else 0)
    headROI=[int(w*.2),0,int(w*.65),int(h*.6)]
    feetROI=[int(w*.30),int(h*.86),int(w*.43),int(h*.14)]
    def box(roi):
        x,y,rw,rh=roi;b=threshold.crop((x,y,x+rw,y+rh)).getbbox();return [b[0]+x,b[1]+y,b[2]+x,b[3]+y]
    hb=box(headROI);fb=box(feetROI);top=hb[1];sole=fb[3]-1;bodyH=sole-top+1
    source=str(O.parent/'original.png') if i==0 else sel[i-1]['source']
    scalpH=m['chin']-m['crown']+1;fx,fy,fw,fh=m['face'];faceArea=fw*fh
    e=dict(variant=i,label=labels[i],file=file,source=source,sourceSha256=sha(source),sha256=sha(p),sourceBytesMatch=sha(p)==sha(source),width=w,height=h,mode=im.mode,alphaMinMax=list(a.getextrema()),alpha32Bounds=list(threshold.getbbox()),hairTop=top,scalpCrown=dict(y=m['crown'],estimated=True,uncertaintyPx=m['crownError'],method='Forehead/temple continuation, ear level and plausible cranial oval under hair; not directly measurable, not hair whorl/spike top'),chin=dict(y=m['chin'],estimated=True,uncertaintyPx=8),sole=sole,bodyHeight=bodyH,bodyBounds=dict(x=m['bodyX'][0],y=top,width=m['bodyX'][1]-m['bodyX'][0],height=bodyH,xEstimated=True),footAnchor=dict(x=m['footX'],y=sole,xEstimated=True),faceBounds=dict(x=fx,y=fy,width=fw,height=fh,estimated=True,uncertaintyPx=12,meaning='visible facial envelope rectangle; includes fringe occlusion and facial features, not exact segmented skin mask'),faceEnvelopeAreaProxy=faceArea,scalpCrownToChin=scalpH,scalpCrownToSole=sole-m['crown']+1,scalpHeadUnits=(sole-m['crown']+1)/scalpH,hairInclusiveHeadUnits=bodyH/(m['chin']-top+1),headToDisplayHeight=scalpH/bodyH,faceWidthToDisplayHeight=fw/bodyH,faceHeightToDisplayHeight=fh/bodyH,faceEnvelopeAreaToDisplayHeightSquared=faceArea/(bodyH*bodyH),measurement=dict(alphaThreshold=32,headROI=headROI,feetROI=feetROI,headAlphaBounds=hb,feetAlphaBounds=fb,bodyYAlphaMeasured=True,soleUncertaintyPx=3,bodyXUncertaintyPx=20,footXUncertaintyPx=20),designPurpose=labels[i],userApproved=False)
    e['displaySizes']={str(size):dict(faceWidth=fw*size/bodyH,faceHeight=fh*size/bodyH,scalpHeadHeight=scalpH*size/bodyH) for size in [57,72,500]}
    entries.append(e)
orig=entries[0]
for e in entries:
    e['relativeToOriginalAtEqualHairTopToSoleHeight']=dict(scalpHeadLinearRatio=e['headToDisplayHeight']/orig['headToDisplayHeight'],faceWidthRatio=e['faceWidthToDisplayHeight']/orig['faceWidthToDisplayHeight'],faceHeightRatio=e['faceHeightToDisplayHeight']/orig['faceHeightToDisplayHeight'],faceEnvelopeAreaProxyRatio=e['faceEnvelopeAreaToDisplayHeightSquared']/orig['faceEnvelopeAreaToDisplayHeightSquared'])
save(O/'asset-manifest.json',dict(schemaVersion=3,task='MAIN01-20261109-DBF50341',iteration=3,coordinateSystem='native pixels, top-left origin; hairTop~sole is display height; hidden scalpCrown~chin is estimated anatomical head unit; the two are distinct',allRatiosAreEstimatesNotUserConfirmed=True,sourceImagesResampled=False,assets=entries))
full='';faces='';games={57:'',72:''}
for e in entries:
    sc=500/e['bodyHeight'];x=239-e['footAnchor']['x']*sc;y=570-e['sole']*sc
    full+=f'''<article><header>{e['label']}</header><button class="stage" onclick="show('{e['file']}','{e['label']}')"><img src="{e['file']}" style="width:{e['width']*sc:.5f}px;left:{x:.5f}px;top:{y:.5f}px"><i></i></button></article>'''
    face=e['faceBounds'];s2=sc*2;cx=face['x']+face['width']/2;cy=face['y']+face['height']/2
    faces+=f'''<article><header>{e['label']}</header><div class="face"><img src="{e['file']}" style="width:{e['width']*s2:.5f}px;left:{239-cx*s2:.5f}px;top:{160-cy*s2:.5f}px"></div></article>'''
    for size in [57,72]:
        s=size/e['bodyHeight'];games[size]+=f'''<div class="gamecell"><b>{'기존' if e['variant']==0 else str(e['variant'])}</b><div class="tiny" style="height:{size+20}px"><img data-display-height="{size}" src="{e['file']}" style="width:{e['width']*s:.6f}px;left:calc(50% - {e['footAnchor']['x']*s:.6f}px);top:{size+10-e['sole']*s:.6f}px"></div></div>'''
html='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>금발 전사 · 두상·얼굴 확대 4안</title><style>*{box-sizing:border-box}body{margin:0;background:#eeede9;color:#272c34;font:16px 'Malgun Gothic',sans-serif}main{padding:16px}h1{margin:0 0 6px;font-size:25px}h2{font-size:20px;margin:14px 0 6px}p{margin:0 0 8px;color:#606874}nav{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}nav a,nav button{font:inherit;padding:8px 12px;border:1px solid #bcc4cd;background:white;border-radius:6px;color:#27374d;text-decoration:none}.viewport{overflow:hidden;width:100%}.board{display:grid;grid-template-columns:repeat(5,480px);gap:8px;width:2432px;transform-origin:top left}article{background:#faf9f5;border:1px solid #ccd0d6;border-radius:8px;overflow:hidden}header{height:46px;padding:11px 14px;font-size:20px;font-weight:bold}.stage{display:block;width:478px;height:610px;position:relative;overflow:hidden;border:0;background:transparent;padding:0;cursor:zoom-in}.stage img,.face img,.tiny img{position:absolute;max-width:none}.stage i{position:absolute;left:8px;right:8px;top:570px;border-top:1px dashed #a4aab3;pointer-events:none}.face{height:320px;position:relative;overflow:hidden}.games{max-width:1000px;margin:0 auto 12px}.gamegrid{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;background:#faf9f5;border:1px solid #ccd0d6;border-radius:8px;padding:8px}.gamecell{text-align:center;min-width:0}.gamecell b{font-size:14px}.tiny{position:relative;overflow:visible;width:100%}.gamenote{font-size:13px}body.dark{background:#1c2330;color:#edf2fb}body.dark article,body.dark .gamegrid{background:#2b3546;border-color:#4c596b}body.dark p{color:#c9d1df}dialog{border:0;border-radius:8px;background:#ece9e2;max-width:96vw;max-height:95vh;padding:12px}dialog button{float:right;padding:8px 12px}dialog img{max-width:90vw;max-height:80vh;display:block;object-fit:contain}.mobile-labels{display:none}body.capture nav{display:none}@media(max-width:600px){main{padding:12px}h1{font-size:20px}h2{font-size:16px}p{font-size:12px}.mobile-labels{display:grid;grid-template-columns:repeat(5,1fr);text-align:center;font-size:14px;font-weight:bold}.gamegrid{gap:0;padding:6px 0}}</style><main><h1>금발 전사 · 실제 두상·얼굴 확대 4안</h1><p>금발 헤어 유지 · 모발끝과 추정 두상 정수리를 분리 · 사용자 선택용 시안</p><nav><button onclick="document.body.classList.toggle('dark')">밝게 / 어둡게</button><a href="comparison.png" target="_blank">전체 비교 PNG</a><a href="asset-manifest.json" target="_blank">측정·추정값</a><a href="검수.md" target="_blank">검수 기록</a></nav><h2>전체 몸 비교 — 모발끝~발바닥의 표시 높이·발선 동일</h2><div class="mobile-labels"><span>기존</span><span>1</span><span>2</span><span>3</span><span>4</span></div><div class="viewport" data-height="658"><div class="board">'''+full+'''</div></div><h2>얼굴 확대 — 위 전신 표시 배율에 모두 같은 2배 적용</h2><p>얼굴을 각각 같은 크기로 확대하지 않았습니다. 추정 두상 정수리는 머리카락 아래에 있어 오차가 있습니다.</p><div class="viewport" data-height="368"><div class="board">'''+faces+'''</div></div><section class="games"><h2>작은 게임 크기 관찰 · 57 CSS px</h2><div class="gamegrid">'''+games[57]+'''</div><h2>작은 게임 크기 관찰 · 72 CSS px</h2><div class="gamegrid">'''+games[72]+'''</div><p class="gamenote">모두 모발끝~발바닥 기준 실제 CSS 높이57/72px · 갤러리 관찰이며 게임 통합·실기기 검증이 아닙니다.</p></section><p>개별 PNG는 생성 원본 바이트를 유지합니다. 표시만 등비 등록하며 두상·얼굴 경계는 추정입니다. 공통 비율 채택·사용자 미적 합격 대기.</p></main><dialog><button onclick="document.querySelector('dialog').close()">닫기</button><p id="caption"></p><img id="large"></dialog><script>function fit(){for(const vp of document.querySelectorAll('.viewport')){let s=vp.clientWidth/2432;vp.querySelector('.board').style.transform=`scale(${s})`;vp.style.height=(Number(vp.dataset.height)*s)+'px'}}function show(file,label){document.querySelector('#large').src=file;document.querySelector('#caption').textContent=label;document.querySelector('dialog').showModal()}for(const vp of document.querySelectorAll('.viewport'))new ResizeObserver(fit).observe(vp);fit();window.addEventListener('load',fit)</script></html>'''
(O/'index.html').write_text(html,encoding='utf-8')
print(json.dumps([{k:e[k] for k in ['file','width','height','hairTop','scalpCrown','chin','sole','bodyHeight','relativeToOriginalAtEqualHairTopToSoleHeight','displaySizes']} for e in entries],ensure_ascii=False,indent=2))
